package app.conversions;

import app.application_models.CustomerForm;
import app.application_models.CustomerState;
import app.dtos.CustomerCreate;
import app.dtos.CustomerRead;
import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDateTime;
import java.time.ZoneOffset;
import java.util.Map;

/** Conversions between the application models and the "customers" table: what the service takes and returns. */
public final class CustomerConversions {
    private CustomerConversions() {}

    /** A CustomerForm as the customers table takes it. */
    public static CustomerCreate customerFormToCustomerCreate(CustomerForm model) {
        return new CustomerCreate(
                model.getEmail(),
                String.join(" ", String.valueOf(model.getFirstName()), String.valueOf(model.getLastName())),
                pair(Map.ofEntries(Map.entry("ACTIVE", "active"), Map.entry("BLOCKED", "blocked")), model.getStatus(), null),
                LocalDateTime.ofInstant(Instant.ofEpochSecond(model.getSignedUp()), ZoneOffset.UTC),
                (int) Math.round((model.getBalance().doubleValue() * 100)),
                null, // TODO: nickname: the matching waits for review (nickname)
                null // TODO: country: no field of the model gives it
        );
    }

    /** A row of the customers table as a CustomerForm. */
    public static CustomerForm customerReadToCustomerForm(CustomerRead row) {
        CustomerForm model = new CustomerForm();
        model.setEmail(row.getEmail());
        model.setFirstName(null); // TODO: firstName: Mapper's relation only goes the other way (firstName, lastName)
        model.setLastName(null); // TODO: lastName: Mapper's relation only goes the other way (firstName, lastName)
        model.setStatus(switch (pair(Map.ofEntries(Map.entry("active", "ACTIVE"), Map.entry("blocked", "BLOCKED")), row.getStatus(), null)) { case "ACTIVE" -> CustomerState.ACTIVE; case "BLOCKED" -> CustomerState.BLOCKED; default -> throw new IllegalArgumentException("No CustomerState for this value"); });
        model.setSignedUp(row.getCreatedAt().toInstant(ZoneOffset.UTC).getEpochSecond());
        model.setBalance(BigDecimal.valueOf((row.getBalanceCents().doubleValue() / 100)));
        model.setNickname(null); // TODO: nickname: the matching waits for review (nickname)
        return model;
    }

    /** The value an enum pair gives, or the fallback; a value without a pair is an error. */
    private static String pair(Map<String, String> pairs, Object value, String fallback) {
        String found = pairs.getOrDefault(String.valueOf(value), fallback);
        if (found == null) throw new IllegalArgumentException("No pair for " + value);
        return found;
    }
}

