package app.repositories;

import app.common.Page;
import app.entities.Customer;
import app.errors.ConflictException;
import jakarta.persistence.EntityManager;
import jakarta.persistence.EntityTransaction;
import jakarta.persistence.PersistenceException;
import java.util.List;
import java.util.Optional;

/** Keeps customers rows in the database, through an EntityManager. A write joins the transaction already open, or commits at once. */
public class SqlCustomerRepository implements CustomerRepository {
    protected final EntityManager entityManager;

    public SqlCustomerRepository(EntityManager entityManager) {
        this.entityManager = entityManager;
    }

    @Override
    public Optional<Customer> findById(Integer id) {
        return entityManager.createQuery("select e from Customer e where e.id = :id", Customer.class).setParameter("id", id)
                .getResultStream()
                .findFirst();
    }

    @Override
    public Page<Customer> list(int offset, int limit) {
        List<Customer> items = entityManager.createQuery("select e from Customer e order by e.id", Customer.class)
                .setFirstResult(offset)
                .setMaxResults(limit)
                .getResultList();
        long total = entityManager.createQuery("select count(e) from Customer e", Long.class).getSingleResult();
        return new Page<>(items, total, offset, limit);
    }

    @Override
    public Optional<Customer> findByEmail(String email) {
        return entityManager.createQuery("select e from Customer e where e.email = :email", Customer.class).setParameter("email", email)
                .getResultStream()
                .findFirst();
    }

    @Override
    public Customer insert(Customer entity) {
        try {
            inTransaction(() -> {
                entityManager.persist(entity);
                entityManager.flush();
                // Reads back what the database filled: the key, defaults
                entityManager.refresh(entity);
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Customer", "the database refused the change: " + error.getMessage());
        }
        return entity;
    }

    @Override
    public Customer update(Customer entity) {
        Customer[] stored = new Customer[1];
        try {
            inTransaction(() -> {
                stored[0] = entityManager.merge(entity);
                entityManager.flush();
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Customer", "the database refused the change: " + error.getMessage());
        }
        return stored[0];
    }

    @Override
    public void delete(Customer entity) {
        try {
            inTransaction(() -> {
                entityManager.remove(entityManager.contains(entity) ? entity : entityManager.merge(entity));
                entityManager.flush();
            });
        } catch (PersistenceException error) {
            throw new ConflictException("Customer", "the database refused the change: " + error.getMessage());
        }
    }

    /** Runs a write in the transaction already open, or in one of its own. */
    private void inTransaction(Runnable write) {
        EntityTransaction transaction = entityManager.getTransaction();
        if (transaction.isActive()) {
            write.run();
            return;
        }
        transaction.begin();
        try {
            write.run();
            transaction.commit();
        } catch (RuntimeException error) {
            if (transaction.isActive()) transaction.rollback();
            throw error;
        }
    }
}

