package app.services;

import app.UnitOfWork;
import app.common.Page;
import app.dtos.CustomerCreate;
import app.dtos.CustomerRead;
import app.dtos.CustomerUpdate;
import app.entities.Customer;
import app.errors.ConflictException;
import app.errors.FieldError;
import app.errors.NotFoundException;
import app.errors.ValidationFailedException;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;

/** Operations on customers. Each write runs in its own transaction. */
public class CustomerService {
    private final UnitOfWork uow;

    public CustomerService(UnitOfWork uow) {
        this.uow = uow;
    }

    /** Checks the values against the rules of the "customers" table, and the rows they point to; throws ValidationFailedException with every problem. */
    private void validate(UnitOfWork uow, Map<String, Object> values, Customer current) {
        boolean creating = current == null;
        List<FieldError> errors = new ArrayList<>();
        {
            Object value = values.get("email");
            if (value == null) {
                if (creating || values.containsKey("email")) errors.add(new FieldError("email", "is required"));
            } else {
                if (value instanceof String text && text.length() > 120) errors.add(new FieldError("email", "is longer than 120 characters"));
            }
        }
        {
            Object value = values.get("fullName");
            if (value == null) {
                if (creating || values.containsKey("fullName")) errors.add(new FieldError("full_name", "is required"));
            } else {
                if (value instanceof String text && text.length() > 120) errors.add(new FieldError("full_name", "is longer than 120 characters"));
            }
        }
        {
            Object value = values.get("status");
            if (value == null) {
                if (creating || values.containsKey("status")) errors.add(new FieldError("status", "is required"));
            } else {
                if (value instanceof String text && text.length() > 10) errors.add(new FieldError("status", "is longer than 10 characters"));
                if (!List.of("active", "blocked").contains(String.valueOf(value))) errors.add(new FieldError("status", "must be one of: active, blocked"));
            }
        }
        {
            Object value = values.get("createdAt");
            if (value == null) {
                if (creating || values.containsKey("createdAt")) errors.add(new FieldError("created_at", "is required"));
            }
        }
        {
            Object value = values.get("balanceCents");
            if (value == null) {
                if (creating || values.containsKey("balanceCents")) errors.add(new FieldError("balance_cents", "is required"));
            }
        }
        {
            Object value = values.get("nickname");
            if (value != null) {
                if (value instanceof String text && text.length() > 40) errors.add(new FieldError("nickname", "is longer than 40 characters"));
            }
        }
        {
            Object value = values.get("country");
            if (value == null) {
                if (creating || values.containsKey("country")) errors.add(new FieldError("country", "is required"));
            } else {
                if (value instanceof String text && text.length() > 2) errors.add(new FieldError("country", "is longer than 2 characters"));
            }
        }
        if (!errors.isEmpty()) throw new ValidationFailedException("Customer", errors);
    }

    /** Values that must be unique are not taken by another row. */
    private void checkUnique(UnitOfWork uow, Map<String, Object> values, Customer current) {
        {
            String email = (String) (values.containsKey("email") ? values.get("email") : current == null ? null : current.getEmail());
            if (email != null) {
                Optional<Customer> other = uow.customers().findByEmail(email);
                if (other.isPresent() && (current == null || !Objects.equals(other.get().getId(), current.getId())))
                    throw new ConflictException("Customer", "email is already taken", List.of("email"));
            }
        }
    }

    /** Every check before a write: the values, the rows they point to, the unique values. */
    private void check(UnitOfWork uow, Map<String, Object> values, Customer current) {
        validate(uow, values, current);
        checkUnique(uow, values, current);
    }

    /** Sets the given values on the entity. */
    private static void apply(Customer entity, Map<String, Object> values) {
        if (values.containsKey("email")) entity.setEmail((String) values.get("email"));
        if (values.containsKey("fullName")) entity.setFullName((String) values.get("fullName"));
        if (values.containsKey("status")) entity.setStatus((String) values.get("status"));
        if (values.containsKey("createdAt")) entity.setCreatedAt((LocalDateTime) values.get("createdAt"));
        if (values.containsKey("balanceCents")) entity.setBalanceCents((Integer) values.get("balanceCents"));
        if (values.containsKey("nickname")) entity.setNickname((String) values.get("nickname"));
        if (values.containsKey("country")) entity.setCountry((String) values.get("country"));
    }

    /** The Customer with this key; NotFoundException when there is none. */
    private Customer find(UnitOfWork uow, Integer id) {
        return uow.customers().findById(id).orElseThrow(() -> new NotFoundException("Customer", id));
    }

    /** The Customer as services return it. */
    private static CustomerRead read(Customer entity) {
        return new CustomerRead(entity.getId(), entity.getEmail(), entity.getFullName(), entity.getStatus(), entity.getCreatedAt(), entity.getBalanceCents(), entity.getNickname(), entity.getCountry());
    }

    /** The values an update gives, by field. */
    private static Map<String, Object> given(CustomerUpdate changes) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (changes.getEmail() != null && changes.getEmail().isPresent()) values.put("email", changes.getEmail().value());
        if (changes.getFullName() != null && changes.getFullName().isPresent()) values.put("fullName", changes.getFullName().value());
        if (changes.getStatus() != null && changes.getStatus().isPresent()) values.put("status", changes.getStatus().value());
        if (changes.getCreatedAt() != null && changes.getCreatedAt().isPresent()) values.put("createdAt", changes.getCreatedAt().value());
        if (changes.getBalanceCents() != null && changes.getBalanceCents().isPresent()) values.put("balanceCents", changes.getBalanceCents().value());
        if (changes.getNickname() != null && changes.getNickname().isPresent()) values.put("nickname", changes.getNickname().value());
        if (changes.getCountry() != null && changes.getCountry().isPresent()) values.put("country", changes.getCountry().value());
        return values;
    }

    /** Stores a new Customer after checking it. */
    public CustomerRead createCustomer(CustomerCreate data) {
        Map<String, Object> values = new LinkedHashMap<>();
        if (data.getEmail() != null) values.put("email", data.getEmail());
        if (data.getFullName() != null) values.put("fullName", data.getFullName());
        if (data.getStatus() != null) values.put("status", data.getStatus());
        if (data.getCreatedAt() != null) values.put("createdAt", data.getCreatedAt());
        if (data.getBalanceCents() != null) values.put("balanceCents", data.getBalanceCents());
        if (data.getNickname() != null) values.put("nickname", data.getNickname());
        if (data.getCountry() != null) values.put("country", data.getCountry());
        return uow.transaction((uow) -> {
            check(uow, values, null);
            Customer entity = new Customer();
            apply(entity, values);
            return read(uow.customers().insert(entity));
        });
    }

    /** The Customer with this key; NotFoundException when there is none. */
    public CustomerRead getCustomer(Integer id) {
        return read(find(uow, id));
    }

    /** A page of customers, by primary key. */
    public Page<CustomerRead> listCustomers(int offset, int limit) {
        return uow.customers().list(offset, limit).map(CustomerService::read);
    }

    /** Changes the given values of a Customer. */
    public CustomerRead updateCustomer(Integer id, CustomerUpdate changes) {
        Map<String, Object> values = given(changes);
        return uow.transaction((uow) -> {
            Customer current = find(uow, id);
            check(uow, values, current);
            apply(current, values);
            return read(uow.customers().update(current));
        });
    }

    /** Deletes a Customer. */
    public void deleteCustomer(Integer id) {
        uow.transaction((uow) -> {
            Customer current = find(uow, id);
            uow.customers().delete(current);
            return null;
        });
    }

    /** The Customer with this email, if there is one. */
    public Optional<CustomerRead> findCustomerByEmail(String email) {
        return uow.customers().findByEmail(email).map(CustomerService::read);
    }
}

