            assertThrows(ConflictException.class, () -> service.createCustomer(createOf(again)));
        }

        @Test
        void keepsItsOwnUniqueValue() {
            CustomerService service = new CustomerService(uow);
            int n = 100;
            Customer row = Factories.newCustomer(1);
            var created = service.createCustomer(createOf(row));
            service.updateCustomer(created.getId(), new CustomerUpdate(Patch.of(created.getEmail()), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent()));
        }

        @Test
        void saysWhenARowIsMissing() {
            CustomerService service = new CustomerService(uow);
            assertThrows(NotFoundException.class, () -> service.getCustomer(999999));
        }

        @Test
        void changesARow() {
            CustomerService service = new CustomerService(uow);
            int n = 100;
            Customer row = Factories.newCustomer(1);
            var created = service.createCustomer(createOf(row));
            var updated = service.updateCustomer(created.getId(), new CustomerUpdate(Patch.absent(), Patch.of("changed"), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent(), Patch.absent()));
