            service.deleteCustomer(created.getId());
            assertThrows(NotFoundException.class, () -> service.getCustomer(created.getId()));
        }
    }

    /** The create DTO of a row the factories made. */
    private static CustomerCreate createOf(Customer row) {
        return new CustomerCreate(row.getEmail(), row.getFullName(), row.getStatus(), row.getCreatedAt(), row.getBalanceCents(), row.getNickname(), row.getCountry());
    }
}

